from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    base = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Grid separators are rows or columns predominantly filled with a
    # non-background color.
    row_lines, col_lines = [], []
    for r in range(h):
        color, count = Counter(grid[r]).most_common(1)[0]
        if color != base and count / w >= 0.55:
            row_lines.append(r)
    for c in range(w):
        color, count = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if color != base and count / h >= 0.55:
            col_lines.append(c)

    if len(row_lines) < 2 or len(col_lines) < 2:
        return [row[:] for row in grid]

    # The regular separator color is the most common non-background color
    # across the detected lines; other colors at their crossings are marks.
    counts = Counter()
    for r in row_lines:
        counts.update(v for v in grid[r] if v != base)
    for c in col_lines:
        counts.update(grid[r][c] for r in range(h) if grid[r][c] != base)
    divider = counts.most_common(1)[0][0]

    out = []
    for i in range(len(row_lines) - 1):
        row = []
        for j in range(len(col_lines) - 1):
            corners = (
                grid[row_lines[i]][col_lines[j]],
                grid[row_lines[i]][col_lines[j + 1]],
                grid[row_lines[i + 1]][col_lines[j]],
                grid[row_lines[i + 1]][col_lines[j + 1]],
            )
            color = corners[0]
            if color == base or color == divider or any(v != color for v in corners):
                color = base
            row.append(color)
        out.append(row)

    # Discard empty background margins.
    while out and all(v == base for v in out[0]):
        out.pop(0)
    while out and all(v == base for v in out[-1]):
        out.pop()
    if out:
        while all(row[0] == base for row in out):
            for row in out:
                row.pop(0)
        while all(row[-1] == base for row in out):
            for row in out:
                row.pop()

    return out
